'use client'

import React, { useState } from 'react'
import { useSession } from 'next-auth/react'
import { Calendar } from '@/components/ui/calendar'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Eye, Trash2, ChevronLeft, ChevronRight } from 'lucide-react'
import { useGetCalendarGrants } from '@/lib/grantCalendarApi'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import {
  format,
  startOfMonth,
  endOfMonth,
  addMonths,
  subMonths,
} from 'date-fns'
import Image from 'next/image'

export default function GrantCalendar() {
  const { data: session } = useSession()
  const accessToken = session?.user?.accessToken || ''

  const [selectedMonth, setSelectedMonth] = useState(new Date())
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date())
  const [currentPage, setCurrentPage] = useState(1)
  const [isDetailsOpen, setIsDetailsOpen] = useState(false)
  const [viewingGrant, setViewingGrant] = useState<any | null>(null)

  // Get start and end dates for the selected month
  const startDate = format(startOfMonth(selectedMonth), 'yyyy-MM-dd')
  const endDate = format(endOfMonth(selectedMonth), 'yyyy-MM-dd')

  const { data, isLoading } = useGetCalendarGrants(
    accessToken,
    startDate,
    endDate,
    currentPage,
    10
  )

  const grants = data?.data.items || []
  const totalPages = Math.ceil((data?.data.total || 0) / 10)
  const totalData = data?.data.total || 0

  // Get grants with deadlines in selected month
  const grantsWithDeadlines = grants.filter((grant) => {
    const deadline = new Date(grant.deadline)
    return (
      deadline >= startOfMonth(selectedMonth) &&
      deadline <= endOfMonth(selectedMonth)
    )
  })

  const handleViewGrant = (grant: any) => {
    setViewingGrant(grant)
    setIsDetailsOpen(true)
  }

  const handleMonthChange = (direction: 'prev' | 'next') => {
    setSelectedMonth(
      direction === 'prev'
        ? subMonths(selectedMonth, 1)
        : addMonths(selectedMonth, 1)
    )
    setCurrentPage(1)
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'open':
        return 'bg-green-100 text-green-800'
      case 'upcoming':
        return 'bg-blue-100 text-blue-800'
      case 'closed':
        return 'bg-red-100 text-red-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-gray-900">Grant Calendar</h1>
        <p className="text-gray-600 mt-1">
          View and manage grants by deadline dates
        </p>
      </div>

      <div className="grid grid-cols-1 gap-6">
        {/* Calendar Section */}
        <Card className=" w-full">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
            <CardTitle className="text-lg font-semibold">
              {format(selectedMonth, 'MMMM yyyy')}
            </CardTitle>
            <div className="flex gap-1">
              <Button
                variant="outline"
                size="icon"
                onClick={() => handleMonthChange('prev')}
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>
              <Button
                variant="outline"
                size="icon"
                onClick={() => handleMonthChange('next')}
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            <Calendar
              mode="single"
              selected={selectedDate}
              onSelect={setSelectedDate}
              month={selectedMonth}
              onMonthChange={setSelectedMonth}
              className="rounded-md border max-w-full "
              modifiers={{
                hasGrant: grantsWithDeadlines.map((g) => new Date(g.deadline)),
              }}
              modifiersStyles={{
                hasGrant: {
                  backgroundColor: '#DBEAFE',
                  fontWeight: 'bold',
                },
              }}
            />
          </CardContent>
        </Card>

        {/* Grants List Section */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>
              Grants in {format(selectedMonth, 'MMMM yyyy')}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="text-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
                <p className="text-gray-500 mt-2">Loading grants...</p>
              </div>
            ) : grants.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                <p className="text-lg">No grants found for this period</p>
              </div>
            ) : (
              <div className="space-y-4">
                {/* Table Header */}
                <div className="grid grid-cols-12 gap-4 pb-3 border-b font-semibold text-sm text-gray-700">
                  <div className="col-span-4">Title</div>
                  <div className="col-span-2 text-center">Type</div>
                  <div className="col-span-2 text-center">Funding</div>
                  <div className="col-span-2 text-center">Status</div>
                  <div className="col-span-2 text-center">Actions</div>
                </div>

                {/* Table Rows */}
                {grants.map((grant) => (
                  <div
                    key={grant._id}
                    className="grid grid-cols-12 gap-4 py-3 border-b hover:bg-gray-50 transition-colors items-center"
                  >
                    <div className="col-span-4">
                      <p className="font-medium text-gray-900 line-clamp-1">
                        {grant.title}
                      </p>
                      <p className="text-sm text-gray-500">
                        {format(new Date(grant.deadline), 'MMM dd, yyyy')}
                      </p>
                    </div>
                    <div className="col-span-2 text-center text-sm text-gray-600">
                      {grant.type}
                    </div>
                    <div className="col-span-2 text-center text-sm font-medium text-gray-900">
                      {grant.funding}
                    </div>
                    <div className="col-span-2 text-center">
                      <span
                        className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(
                          grant.status
                        )}`}
                      >
                        {grant.status}
                      </span>
                    </div>
                    <div className="col-span-2 flex justify-center gap-2">
                      <button
                        onClick={() => handleViewGrant(grant)}
                        className="text-blue-600 hover:text-blue-800 transition-colors p-1"
                        title="View"
                      >
                        <Eye className="w-5 h-5" />
                      </button>
                      <button
                        className="text-red-600 hover:text-red-800 transition-colors p-1"
                        title="Delete"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </div>
                ))}

                {/* Pagination */}
                {totalPages > 1 && (
                  <div className="flex items-center justify-between pt-4 border-t">
                    <div className="text-sm text-gray-600">
                      Showing {(currentPage - 1) * 10 + 1} to{' '}
                      {Math.min(currentPage * 10, totalData)} of {totalData}{' '}
                      results
                    </div>
                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() =>
                          setCurrentPage((p) => Math.max(1, p - 1))
                        }
                        disabled={currentPage === 1}
                      >
                        <ChevronLeft className="h-4 w-4" />
                      </Button>
                      {Array.from({ length: totalPages }, (_, i) => i + 1).map(
                        (page) => (
                          <Button
                            key={page}
                            variant={
                              currentPage === page ? 'default' : 'outline'
                            }
                            size="sm"
                            onClick={() => setCurrentPage(page)}
                            className="min-w-[32px]"
                          >
                            {page}
                          </Button>
                        )
                      )}
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() =>
                          setCurrentPage((p) => Math.min(totalPages, p + 1))
                        }
                        disabled={currentPage === totalPages}
                      >
                        <ChevronRight className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* View Details Dialog */}
      <Dialog open={isDetailsOpen} onOpenChange={setIsDetailsOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="text-2xl font-semibold">
              Grant Details
            </DialogTitle>
          </DialogHeader>

          {viewingGrant && (
            <div className="space-y-6 py-4">
              <div>
                <h3 className="text-2xl font-bold text-gray-900 mb-3">
                  {viewingGrant.title}
                </h3>

                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <span className="font-semibold text-gray-700">Type:</span>
                    <span className="ml-2 text-gray-600">
                      {viewingGrant.type}
                    </span>
                  </div>
                  <div>
                    <span className="font-semibold text-gray-700">
                      Funding:
                    </span>
                    <span className="ml-2 text-gray-600">
                      {viewingGrant.funding}
                    </span>
                  </div>
                  <div>
                    <span className="font-semibold text-gray-700">
                      Deadline:
                    </span>
                    <span className="ml-2 text-gray-600">
                      {format(new Date(viewingGrant.deadline), 'MMM dd, yyyy')}
                    </span>
                  </div>
                  <div>
                    <span className="font-semibold text-gray-700">Status:</span>
                    <span
                      className={`ml-2 px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(
                        viewingGrant.status
                      )}`}
                    >
                      {viewingGrant.status}
                    </span>
                  </div>
                </div>
              </div>

              <div>
                <h4 className="font-semibold text-lg mb-2">Location</h4>
                <div className="flex flex-wrap gap-2">
                  {viewingGrant.location?.map((loc: string, i: number) => (
                    <span
                      key={i}
                      className="px-3 py-1 bg-gray-100 rounded-full text-sm"
                    >
                      {loc}
                    </span>
                  ))}
                </div>
              </div>

              <div>
                <h4 className="font-semibold text-lg mb-2">Industry</h4>
                <div className="flex flex-wrap gap-2">
                  {viewingGrant.industry?.map((ind: string, i: number) => (
                    <span
                      key={i}
                      className="px-3 py-1 bg-blue-100 rounded-full text-sm"
                    >
                      {ind}
                    </span>
                  ))}
                </div>
              </div>

              <div>
                <h4 className="font-semibold text-lg mb-2">Activity</h4>
                <div className="flex flex-wrap gap-2">
                  {viewingGrant.activity?.map((act: string, i: number) => (
                    <span
                      key={i}
                      className="px-3 py-1 bg-green-100 rounded-full text-sm"
                    >
                      {act}
                    </span>
                  ))}
                </div>
              </div>

              <div>
                <h4 className="font-semibold text-lg mb-2">Description</h4>
                <p className="text-gray-700 leading-relaxed">
                  {viewingGrant.description}
                </p>
              </div>

              {viewingGrant.imageUrl && (
                <div>
                  <h4 className="font-semibold text-lg mb-2">Image</h4>
                  <Image
                    src={viewingGrant.imageUrl}
                    alt={viewingGrant.title}
                    width={600}
                    height={400}
                    className="w-full max-w-md rounded-lg"
                  />
                </div>
              )}

              {viewingGrant.fileUrl && (
                <div>
                  <h4 className="font-semibold text-lg mb-2">Attachment</h4>
                  <a
                    href={viewingGrant.fileUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-blue-600 hover:underline"
                  >
                    Download Document
                  </a>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  )
}
